func (s UsageSnapshotServiceServer) apply(ctx context.Context, ref *rove.UsageSnapshotRef, doc *patchpb.Patch, by string) (*rove.UsageSnapshot, error) {
	plan := &ormpatch.Plan{Entity: usageSnapshotOrmEntity}
	if doc != nil {
		v, err := ormpatch.Compile(usageSnapshotOrmEntity, doc)
		if err != nil {
			if errors.Is(err, ormpatch.ErrUnsupported) {
				return nil, status.Errorf(codes.Unimplemented, "%s", err)
			}
			return nil, status.Errorf(codes.InvalidArgument, "%s", err)
		}
		plan = v
	}

	pred, mod, err := entpatch.Build(plan, usageSnapshotPatchColumns, s.Db.Dialect())
	if err != nil {
		if errors.Is(err, entpatch.ErrValue) {
			return nil, status.Errorf(codes.InvalidArgument, "%s", err)
		}
		return nil, status.Errorf(codes.Internal, "%s", err)
	}

	tx, err := ent1.JoinTx[*ent.Client, *ent.Tx](ctx, s.Db, true)
	if err != nil {
		return nil, err
	}
	defer tx.Close()

	st := s
	st.Db = tx.Db

	k, err := UsageSnapshotGetKey(ctx, st.Db, ref)
	if err != nil {
		return nil, err
	}
	at := &rove.UsageSnapshotRef{}
	at.SetId(k[:])
	p, err := s.narrow(ctx, usagesnapshot.IdEQ(k))
	if err != nil {
		return nil, err
	}

	var previous *rove.UsageSnapshot
	images := snapshotOptions(s.Rec, by)
	if images.Previous && mod != nil {
		u, err := st.snapshot(ctx, p, true)
		if err != nil {
			if ent.IsNotFound(err) {
				return nil, status.Error(codes.NotFound, "resource not found")
			}
			return nil, err
		}
		previous = s.image(u.Proto())
	}
	if mod == nil {
		q := st.Db.UsageSnapshot.Query().Where(p)
		if pred != nil {
			q.Where(predicate.UsageSnapshot(pred))
		}
		if ok, err := q.Exist(ctx); err != nil {
			return nil, err
		} else if !ok {
			return nil, func() error {
				if ok, err := st.Db.UsageSnapshot.Query().Where(p).Exist(ctx); err != nil {
					return err
				} else if !ok {
					return status.Error(codes.NotFound, "UsageSnapshot not found")
				}
				return status.Error(codes.FailedPrecondition, "a test in the patch did not hold")
			}()
		}
	} else {
		q := st.Db.UsageSnapshot.Update().Where(p)
		if pred != nil {
			q.Where(predicate.UsageSnapshot(pred))
		}
		q.Modify(mod)
		if !plan.WritesTo(13) {
			q.SetDateUpdated(st.now())
		}
		if n, err := q.Save(ctx); err != nil {
			if err, ok := err.(*ent.ConstraintError); ok {
				if sqlgraph.IsUniqueConstraintError(err) {
					return nil, status.Error(codes.AlreadyExists, "UsageSnapshot already exists")
				}
				if sqlgraph.IsForeignKeyConstraintError(err) {
					return nil, status.Error(codes.NotFound, "UsageSnapshot: referenced entity not found")
				}
			}
			return nil, err
		} else if n == 0 {
			return nil, func() error {
				if ok, err := st.Db.UsageSnapshot.Query().Where(p).Exist(ctx); err != nil {
					return err
				} else if !ok {
					return status.Error(codes.NotFound, "UsageSnapshot not found")
				}
				return status.Error(codes.FailedPrecondition, "a test in the patch did not hold")
			}()
		}
	}

	out, err := st.Get(ctx, at.Pick())
	if err != nil {
		return nil, err
	}
	if mod != nil {
		var value *rove.UsageSnapshot
		if images.Value {
			value = s.image(out)
		}
		if err := record(ctx, s.Rec, st.Db, Change{
			By:       by,
			Key:      k,
			Patch:    doc,
			Previous: previous, Value: value,
		}); err != nil {
			return nil, err
		}
	}

	if err := tx.Commit(); err != nil {
		return nil, err
	}
	return out, nil
}

func (s UsageSnapshotServiceServer) Erase(ctx context.Context, req *rove.UsageSnapshotRef) (*rove.UsageSnapshotEraseResponse, error) {
	p, err := UsageSnapshotPick(req)
	if err != nil {
		return nil, err
	}
	p, err = s.narrow(ctx, p)
	if err != nil {
		return nil, err
	}

	tx, err := ent1.JoinTx[*ent.Client, *ent.Tx](ctx, s.Db, s.Rec != nil)
	if err != nil {
		return nil, err
	}
	defer tx.Close()

	st := s
	st.Db = tx.Db

	var k any
	var previous *rove.UsageSnapshot
	if s.Rec != nil {
		images := snapshotOptions(s.Rec, rove.UsageSnapshotService_Erase_FullMethodName)
		var v *ent.UsageSnapshot
		var err error
		if images.Previous {
			v, err = st.snapshot(ctx, p, true)
		} else {
			v, err = st.Db.UsageSnapshot.Query().Where(p).Select(usagesnapshot.FieldId).Only(ctx)
		}
		if err != nil {
			if ent.IsNotFound(err) {
				return &rove.UsageSnapshotEraseResponse{}, nil
			}
			return nil, err
		}

		k = v.Id
		if images.Previous {
			previous = s.image(v.Proto())
		}
		p = usagesnapshot.And(p, usagesnapshot.IdEQ(v.Id))
	}

	n, err := st.Db.UsageSnapshot.Delete().Where(p).Exec(ctx)
	if err != nil {
		return nil, err
	}
	if n > 0 {
		if err := record(ctx, s.Rec, st.Db, Change{
			By:       rove.UsageSnapshotService_Erase_FullMethodName,
			Key:      k,
			Previous: previous,
		}); err != nil {
			return nil, err
		}
	}
	if err := tx.Commit(); err != nil {
		return nil, err
	}
	res := &rove.UsageSnapshotEraseResponse{}
	res.SetErased(n > 0)

	return res, nil
}

func UsageSnapshotPick(req *rove.UsageSnapshotRef) (predicate.UsageSnapshot, error) {
	switch req.WhichKey() {
	case rove.UsageSnapshotRef_Id_case:
		if v, err := entuuid.FromBytes(req.GetId()); err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "id: %s", err)
		} else {
			return usagesnapshot.IdEQ(v), nil
		}
	case rove.UsageSnapshotRef_Day_case:
		k := req.GetDay()
		ps := make([]predicate.UsageSnapshot, 0, 2)
		if p, err := TenantPick(k.GetTenant()); err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "day.tenant: %s", err)
		} else {
			ps = append(ps, usagesnapshot.HasTenantWith(p))
		}
		ps = append(ps, usagesnapshot.DayEQ(k.GetDay()))
		return usagesnapshot.And(ps...), nil
	case rove.UsageSnapshotRef_Key_not_set_case:
		return nil, status.Errorf(codes.InvalidArgument, "key not set: UsageSnapshot")
	default:
		return nil, status.Errorf(codes.Unimplemented, "unknown type of key: %s", req.WhichKey())
	}
}

type TenantContractServiceServer struct {
	Store

	rove.UnimplementedTenantContractServiceServer
}

// NewTenantContractServiceServer answers with a server that runs its queries with `db`.
//
// It takes the options of [Server] so that what is built here can be told
// where to report its writes and what it may see. Built without them, it
// reports nowhere and sees everything.
func NewTenantContractServiceServer(db *ent.Client, opts ...Option) rove.TenantContractServiceServer {
	s := Server{Store: Store{Db: db}}
	for _, opt := range opts {
		opt(&s)
	}
	return TenantContractServiceServer{Store: s.Store}
}

// TenantContractNarrow answers with `p` and everything else that narrows a
// read of a TenantContract: the rows that have not been erased, and whatever
// `scope` says of those.
//
// Every read this package makes goes through it, and a read written by
// hand should too -- a List is the one read nothing generates, and so the
// one that would otherwise answer with rows nobody should be given.
func TenantContractNarrow(ctx context.Context, scope Scope, p predicate.TenantContract) (predicate.TenantContract, error) {
	ps := make([]predicate.TenantContract, 0, 3)

	// A row that was erased is not a row a read answers with.
	ps = append(ps, tenantcontract.DateErasedIsNil())
	if p != nil {
		ps = append(ps, p)
	}
	if scope != nil {
		q, err := scope.TenantContractScope(ctx)
		if err != nil {
			return nil, err
		}
		if q != nil {
			ps = append(ps, q)
		}
	}

	switch len(ps) {
	case 0:
		return nil, nil
	case 1:
		return ps[0], nil
	default:
		return tenantcontract.And(ps...), nil
	}
}

// narrow is [TenantContractNarrow] with this server's own scope.
func (s TenantContractServiceServer) narrow(ctx context.Context, p predicate.TenantContract) (predicate.TenantContract, error) {
	return TenantContractNarrow(ctx, s.Scope, p)
}

func (s TenantContractServiceServer) snapshot(ctx context.Context, p predicate.TenantContract, lock bool) (*ent.TenantContract, error) {
	q := s.Db.TenantContract.Query().Where(p)
	q.Modify(func(q *sql.Selector) {
		if lock && s.Db.Dialect() != dialect.SQLite {
			q.ForUpdate()
		}
	})
	return q.Only(ctx)
}
func (s TenantContractServiceServer) image(v *rove.TenantContract) *rove.TenantContract {
	if v == nil {
		return nil
	}
	out := proto.Clone(v).(*rove.TenantContract)
	m := out.ProtoReflect()
	{
		f := m.Descriptor().Fields().ByNumber(2)
		if m.Has(f) {
			trim := func(r protoreflect.Message) {
				r.Range(func(f protoreflect.FieldDescriptor, _ protoreflect.Value) bool {
					if f.Number() != 1 {
						r.Clear(f)
					}
					return true
				})
			}
			trim(m.Get(f).Message())
		}
	}
	return out
}

